/**
 * Architecture Contract: IPFS Service
 * Codifies the public interface of services/ipfs.js.
 * Generated by /architecture-sweep
 */

// Mock env must be set before require
process.env.USE_MOCK_IPFS = 'true';
process.env.NODE_ENV = 'test';

const ipfsService = require('../../src/services/ipfs');

describe('IPFS service interface contract', () => {
  // ── Module exports ──

  test('exports expected public functions', () => {
    expect(typeof ipfsService.upload).toBe('function');
    expect(typeof ipfsService.uploadJson).toBe('function');
    expect(typeof ipfsService.getGatewayUrl).toBe('function');
    expect(typeof ipfsService.fetch).toBe('function');
    expect(typeof ipfsService.unpin).toBe('function');
    expect(typeof ipfsService.listPins).toBe('function');
  });

  test('does not export internal helpers', () => {
    expect(ipfsService.getPinata).toBeUndefined();
    expect(ipfsService.getMimeType).toBeUndefined();
    expect(ipfsService.saveMockStore).toBeUndefined();
  });

  // ── upload() ──

  test('upload returns [uri, events] tuple', async () => {
    const data = Buffer.from('test image data');
    const result = await ipfsService.upload(data, 'test.png');

    expect(Array.isArray(result)).toBe(true);
    expect(result.length).toBe(2);

    const [uri, events] = result;
    expect(typeof uri).toBe('string');
    expect(uri.startsWith('ipfs://')).toBe(true);
    expect(Array.isArray(events)).toBe(true);
    expect(events.length).toBeGreaterThan(0);
    expect(events[0].type).toBe('ipfs.uploaded');
    expect(events[0].mock).toBe(true);
  });

  // ── uploadJson() ──

  test('uploadJson returns [uri, events] tuple', async () => {
    const json = { name: 'Test NFT', description: 'A test' };
    const result = await ipfsService.uploadJson(json, 'metadata.json');

    expect(Array.isArray(result)).toBe(true);
    const [uri, events] = result;
    expect(uri.startsWith('ipfs://')).toBe(true);
    expect(events[0].type).toBe('ipfs.uploaded');
  });

  // ── getGatewayUrl() ──

  test('getGatewayUrl converts ipfs:// URI to HTTP URL', () => {
    const url = ipfsService.getGatewayUrl('ipfs://QmTestHash123');
    expect(url).toContain('/ipfs/QmTestHash123');
    expect(url.startsWith('http')).toBe(true);
  });

  test('getGatewayUrl returns non-IPFS URIs unchanged', () => {
    const url = ipfsService.getGatewayUrl('https://example.com/image.png');
    expect(url).toBe('https://example.com/image.png');
  });

  // ── fetch() ──

  test('fetch retrieves previously uploaded data', async () => {
    const data = Buffer.from('roundtrip test data');
    const [uri] = await ipfsService.upload(data, 'roundtrip.png');

    const fetched = await ipfsService.fetch(uri);
    expect(Buffer.isBuffer(fetched)).toBe(true);
    expect(fetched.equals(data)).toBe(true);
  });

  test('fetch throws for non-existent hash', async () => {
    await expect(ipfsService.fetch('ipfs://QmNonExistent'))
      .rejects.toThrow();
  });

  // ── unpin() ──

  test('unpin returns [success, events] tuple', async () => {
    const data = Buffer.from('to-unpin');
    const [uri] = await ipfsService.upload(data, 'unpin.png');

    const result = await ipfsService.unpin(uri);
    expect(Array.isArray(result)).toBe(true);
    expect(result.length).toBe(2);

    const [success, events] = result;
    expect(typeof success).toBe('boolean');
    expect(events[0].type).toBe('ipfs.unpinned');
  });

  // ── listPins() ──

  test('listPins returns an array', async () => {
    const pins = await ipfsService.listPins();
    expect(Array.isArray(pins)).toBe(true);
  });

  test('listPins respects limit option', async () => {
    // Upload a few items first
    await ipfsService.upload(Buffer.from('pin1'), 'a.png');
    await ipfsService.upload(Buffer.from('pin2'), 'b.png');

    const pins = await ipfsService.listPins({ limit: 1 });
    expect(pins.length).toBeLessThanOrEqual(1);
  });

  // ── Event generation ──

  test('upload generates ipfs.uploaded events with expected fields', async () => {
    const [, events] = await ipfsService.upload(Buffer.from('evt-test'), 'evt.png');
    const e = events[0];
    expect(e).toHaveProperty('type', 'ipfs.uploaded');
    expect(e).toHaveProperty('filename', 'evt.png');
    expect(e).toHaveProperty('cid');
    expect(e).toHaveProperty('uri');
    expect(e).toHaveProperty('mock');
    expect(e).toHaveProperty('timestamp');
  });
});
